/*
 * EN: Convert every supported Meta payload into one canonical event per n8n item.
 * RU: Преобразует каждый поддерживаемый payload Meta в одно каноническое событие на item n8n.
 */
const input = $input.first().json;
const headers = input.headers ?? {};
const payload = input.body ?? input;
const receivedAt = new Date().toISOString();
const entries = Array.isArray(payload.entry) ? payload.entry : [];
const events = [];

// EN: A stable, non-secret fingerprint supports future idempotency storage.
// RU: Стабильный fingerprint без секретов нужен для будущей идемпотентности.
function hashString(value) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function baseEvent(entry, sourceType, sourceIndex) {
  return {
    schema_version: '1.0.0',
    source: 'meta_instagram',
    source_type: sourceType,
    source_index: sourceIndex,
    object: payload.object ?? null,
    instagram_account_id: entry.id ?? null,
    entry_time: entry.time ?? null,
    received_at: receivedAt,
    webhook: {
      path: input.webhookUrl ?? '/webhook/fitnes-mary',
      execution_mode: input.executionMode ?? null,
      forwarded_for: headers['x-forwarded-for'] ?? null,
      signature_sha256: headers['x-hub-signature-256'] ?? null,
      signature_present: Boolean(headers['x-hub-signature-256']),
      signature_verified: false
    }
  };
}

entries.forEach((entry, entryIndex) => {
  const messaging = Array.isArray(entry.messaging) ? entry.messaging : [];
  messaging.forEach((event, eventIndex) => {
    let eventType = 'messaging_unknown';
    if (event.message?.is_echo) eventType = 'message_echo';
    else if (event.message?.text) eventType = 'message_text';
    else if (event.message?.attachments) eventType = 'message_attachment';
    else if (event.postback) eventType = 'postback';
    else if (event.reaction) eventType = 'reaction';
    else if (event.read) eventType = 'read';
    else if (event.delivery) eventType = 'delivery';

    const eventId = event.message?.mid ?? event.postback?.mid ?? null;
    const canonical = {
      ...baseEvent(entry, 'messaging', `${entryIndex}.${eventIndex}`),
      event_type: eventType,
      event_id: eventId,
      event_timestamp: event.timestamp ?? null,
      sender_id: event.sender?.id ?? null,
      recipient_id: event.recipient?.id ?? null,
      message: {
        id: event.message?.mid ?? null,
        text: event.message?.text ?? null,
        is_echo: Boolean(event.message?.is_echo),
        attachments: event.message?.attachments ?? [],
        quick_reply_payload: event.message?.quick_reply?.payload ?? null,
        reply_to_id: event.message?.reply_to?.mid ?? null
      },
      postback: event.postback ?? null,
      reaction: event.reaction ?? null,
      read: event.read ?? null,
      delivery: event.delivery ?? null,
      raw_event: event
    };
    canonical.deduplication_key = eventId || `msg_${hashString(JSON.stringify([entry.id, event.timestamp, event.sender?.id, eventType, eventIndex]))}`;
    events.push({ json: canonical });
  });

  const changes = Array.isArray(entry.changes) ? entry.changes : [];
  changes.forEach((change, changeIndex) => {
    const value = change.value ?? {};
    let eventType = 'change_unknown';
    if (change.field === 'comments' || change.field === 'live_comments') eventType = 'comment';
    else if (change.field === 'mentions') eventType = 'mention';

    const eventId = value.id ?? value.comment_id ?? null;
    const canonical = {
      ...baseEvent(entry, 'change', `${entryIndex}.${changeIndex}`),
      event_type: eventType,
      event_id: eventId,
      event_timestamp: value.created_time ?? entry.time ?? null,
      sender_id: value.from?.id ?? null,
      recipient_id: entry.id ?? null,
      change_field: change.field ?? null,
      change: {
        id: eventId,
        text: value.text ?? null,
        verb: value.verb ?? null,
        media_id: value.media?.id ?? value.media_id ?? null,
        media_product_type: value.media?.media_product_type ?? null,
        parent_id: value.parent_id ?? null,
        from: value.from ?? null
      },
      raw_event: change
    };
    canonical.deduplication_key = eventId || `chg_${hashString(JSON.stringify([entry.id, entry.time, change.field, value, changeIndex]))}`;
    events.push({ json: canonical });
  });
});

// EN: Preserve malformed or empty deliveries for the dead-letter branch.
// RU: Сохраняет некорректные или пустые доставки для ветки dead letter.
if (events.length === 0) {
  events.push({
    json: {
      schema_version: '1.0.0',
      source: 'meta_instagram',
      source_type: 'invalid',
      event_type: 'invalid_payload',
      event_id: null,
      deduplication_key: `invalid_${hashString(JSON.stringify(payload))}`,
      object: payload.object ?? null,
      received_at: receivedAt,
      validation_errors: ['Payload contains no entry.messaging or entry.changes events | Payload не содержит событий entry.messaging или entry.changes'],
      raw_payload: payload
    }
  });
}

return events;

/* EN: Prepare a future DM automation context. RU: Готовит контекст будущей автоматизации Direct. */
return $input.all().map(({ json }) => ({
  json: {
    ...json,
    processing: {
      branch: 'messaging',
      status: json.message?.is_echo ? 'ignored_echo' : 'ready',
      should_reply: !json.message?.is_echo && ['message_text', 'message_attachment', 'postback'].includes(json.event_type),
      conversation_key: [json.instagram_account_id, json.sender_id].filter(Boolean).join(':'),
      normalized_text: (json.message?.text ?? '').trim(),
      language: null,
      intent: null,
      matched_rule_id: null
    },
    future_data: {
      customer_profile: null,
      conversation_history: [],
      attachment_analysis: null,
      generated_reply: null
    }
  }
}));

/* EN: Prepare a future comment automation context. RU: Готовит контекст будущей автоматизации комментариев. */
return $input.all().map(({ json }) => ({
  json: {
    ...json,
    processing: {
      branch: 'comment',
      status: 'ready',
      should_reply_publicly: false,
      should_send_dm: false,
      normalized_text: (json.change?.text ?? '').trim(),
      language: null,
      sentiment: null,
      matched_keyword: null,
      matched_funnel_id: null
    },
    future_data: {
      media: null,
      author_profile: null,
      moderation_result: null,
      public_reply: null,
      private_reply: null
    }
  }
}));

/* EN: Prepare a future mention automation context. RU: Готовит контекст будущей обработки упоминаний. */
return $input.all().map(({ json }) => ({
  json: {
    ...json,
    processing: {
      branch: 'mention',
      status: 'ready',
      normalized_text: (json.change?.text ?? '').trim(),
      should_notify_owner: true,
      should_reply: false
    },
    future_data: {
      media: null,
      author_profile: null,
      notification: null,
      generated_reply: null
    }
  }
}));

/* EN: Keep new Meta event types observable. RU: Сохраняет наблюдаемость новых типов событий Meta. */
return $input.all().map(({ json }) => ({
  json: {
    ...json,
    processing: {
      branch: 'unhandled',
      status: 'needs_mapping',
      should_reply: false,
      reason: `No processor is mapped for ${json.event_type}`
    },
    future_data: {
      handler: null,
      alert: null
    }
  }
}));

/* EN: Build the persistence and action contracts. RU: Формирует контракты хранения и действий. */
return $input.all().map(({ json }) => ({
  json: {
    event: json,
    persistence_record: {
      deduplication_key: json.deduplication_key,
      schema_version: json.schema_version,
      source: json.source,
      event_type: json.event_type,
      event_id: json.event_id,
      instagram_account_id: json.instagram_account_id,
      sender_id: json.sender_id,
      received_at: json.received_at,
      status: json.processing?.status ?? 'unknown',
      payload: json
    },
    action_request: {
      enabled: false,
      action_type: null,
      account_id: json.instagram_account_id,
      recipient_id: json.sender_id,
      message: null,
      idempotency_key: json.deduplication_key,
      metadata: {}
    },
    audit: {
      normalized_at: new Date().toISOString(),
      workflow: 'instagram-base-event-processing',
      workflow_version: '1.0.0'
    }
  }
}));

